-- PACKAGE and SUBTITLES were never queued: packaging happens inside REMUX and
-- TRANSCODE, and subtitles are uploaded or extracted, not generated by a job.
-- Rows of those types cannot exist in a working installation, and are removed
-- first so the type can be replaced.
DELETE FROM "jobs" WHERE "type" IN ('PACKAGE', 'SUBTITLES');

ALTER TYPE "JobType" RENAME TO "JobType_old";

CREATE TYPE "JobType" AS ENUM ('PROBE', 'REMUX', 'TRANSCODE', 'THUMBNAILS', 'AUDIO', 'MARKERS', 'CLEANUP');

ALTER TABLE "jobs" ALTER COLUMN "type" TYPE "JobType" USING ("type"::text::"JobType");

DROP TYPE "JobType_old";
